/// containing PAT, PMT (PID 100), H.264 Video (PID 1279), and AC-3 Audio 5.1 (PID 1283).
public enum PULS24CaptureFixture {
    private static let rawBase64 = ""

    public static var data: Data {
        guard let raw = Data(base64Encoded: rawBase64) else {
            fatalError("Corrupted fixture base64")
        }
        return raw
    }
}
